
      CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS peers(id TEXT PRIMARY KEY, name TEXT UNIQUE NOT NULL, address TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'unknown', lastContact TEXT, failures INTEGER NOT NULL DEFAULT 0, failedSince INTEGER, directoryRevision TEXT, lastError TEXT);
      CREATE TABLE IF NOT EXISTS local_identities(legacyId INTEGER PRIMARY KEY, uuid TEXT UNIQUE NOT NULL);
      CREATE TABLE IF NOT EXISTS credentials(id TEXT PRIMARY KEY, peerId TEXT NOT NULL, hash TEXT NOT NULL UNIQUE);
      CREATE TABLE IF NOT EXISTS identities(peerId TEXT NOT NULL, id TEXT NOT NULL, name TEXT NOT NULL, data TEXT NOT NULL, PRIMARY KEY(peerId,id));